with base as (select id, order_id, carrier, shipped_date, cost, datediff(current_date(), shipped_date) as days_since_shipped_date, coalesce(carrier, 'UNKNOWN') as carrier_clean from shipments where carrier is not null) select id, shipped_date, cost, days_since_shipped_date, carrier_clean, max(days_since_shipped_date) over w_hist as order_id_max_days_since_shipped_date, ntile(3) over w_running as cost_bucket, last_value(carrier, true) over (partition by carrier order by shipped_date, id rows between unbounded preceding and current row) as last_known_carrier, first_value(days_since_shipped_date, true) over w_running_2 as first_known_days_since_shipped_date, first_value(days_since_shipped_date, true) over (partition by order_id order by cost, id rows between unbounded preceding and current row) as first_known_days_since_shipped_date_2 from base window w_hist as (partition by order_id, carrier), w_running as (partition by carrier, order_id order by cost, id), w_running_2 as (partition by order_id order by days_since_shipped_date, id rows between unbounded preceding and current row)
